// All examples are invented Decision Lab records. These helpers only share structure.
const base = (prompt:L, context:L) => ({prompt,context,
  success:l('The supplied evidence supports this answer. Keep its stated limits in your notebook.','दिए प्रमाण इस उत्तर का समर्थन करते हैं। बताई सीमाएँ अपनी नोटबुक में रखें।'),
  correction:l('Compare your submitted work with the supplied records and the specific check below.','अपने जमा काम को दिए रिकॉर्ड और नीचे बताई खास जाँच से मिलाएँ।'),
  hint:l('Use the exact input, target and rule stated in this task; write intermediate work before checking.','इसी काम में दिए इनपुट, लक्ष्य और नियम लें; जाँच से पहले बीच का हिसाब लिखें।')});
const choice=(p:L,c:L,rows:[string,L,L][],correct:string):ChoiceTask=>({...base(p,c),kind:'choice',options:rows.map(([id,label,feedback])=>({id,label,feedback})),correct});
const select=(p:L,c:L,rows:[string,L,L][],expected:string[]):LessonTask=>({...base(p,c),kind:'select',items:rows.map(([id,label,feedback])=>({id,label,feedback})),expected});
const match=(p:L,c:L,rows:[string,L,string,L][],opts:[string,L][]):LessonTask=>({...base(p,c),kind:'match',rows:rows.map(([id,label,answer,explanation])=>({id,label,answer,explanation})),options:opts.map(([id,label])=>({id,label}))});
const nums=(p:L,c:L,rows:[string,L,number,L][]):LessonTask=>({...base(p,c),kind:'number',fields:rows.map(([id,label,answer,explanation])=>({id,label,answer,explanation,min:0}))});
const scene=(title:L,caption:L,dialogue:L)=>({title,caption,dialogue});
const n=(id:string,label:L,x:number,y:number,value?:L):VisualNode=>({id,label,x,y,value,shape:'card'});
const e=(id:string,from:string,to:string)=>({id,from,to});
const s=(text:L,active:string[],moves:[string,number,number][],values:Record<string,L>={},extra:Partial<VisualStep>={}):VisualStep=>({label:text,description:text,active,moves:moves.map(([id,x,y])=>({id,x,y})),values,...extra});
